    assert!(self.total_supply >= reserve_token_balance.ctoken_supply.supply_value());
}

#[test]
fun test_reserve_mint_then_burn_works() {
    let admin = @0xAD;
    let mut scenario_value = sui::test_scenario::begin(admin);

    let ctx = scenario_value.ctx();

    let mut reserve = new<MainMarket, BTC>(ctx, 1);

    let amount = 1000;
    let btc = sui::balance::create_for_testing<BTC>(amount).into_coin(ctx);

    let ctokens = reserve.mint_ctokens<MainMarket, BTC>(btc).into_coin(ctx);
    assert!(ctokens.value() == amount);

    assert!(reserve.util_rate() == float::from_quotient(0, 1));
    assert!(reserve.exchange_rate() == math::float::from_quotient(1, 1));

    let btc = reserve.burn_ctokens<MainMarket, BTC>(ctokens);
    assert!(btc.value() == amount);

    sui::balance::destroy_for_testing(btc);
    std::unit_test::destroy(reserve);
    scenario_value.end();
}

/// Supply 1000 BTC, borrow 100 BTC, utilization rate = 100 / 900, exchange rate = 900 / 1000
#[test]
fun test_reserve_basic_lifecycle_works() {
    let admin = @0xAD;
    let mut scenario_value = sui::test_scenario::begin(admin);

    let ctx = scenario_value.ctx();
    let mut reserve = new<MainMarket, BTC>(ctx, 1);

    let amount = 1000;
    let btc = sui::balance::create_for_testing<BTC>(amount).into_coin(ctx);
    let mut ctokens = reserve.mint_ctokens<MainMarket, BTC>(btc).into_coin(ctx);
    reserve.ensure_invariants_hold<MainMarket, BTC>();

    let mut borrowed_balance = reserve.borrow_amount<MainMarket, BTC>(100);
    reserve.ensure_invariants_hold<MainMarket, BTC>();

    assert!(borrowed_balance.value() == 100);
    assert!(reserve.cash == 900);
    assert!(reserve.debt.eq(float::from(100)));
    assert!(reserve.cash_reserve.is_zero());
    assert!(reserve.exchange_rate() == math::float::from_quotient(1, 1));
    assert!(reserve.util_rate() == float::from_quotient(1, 10));

    // no interest accrue at the moment
    std::unit_test::destroy(borrowed_balance.split(1));
    reserve.repay_amount(borrowed_balance.into_coin(ctx));
    reserve.ensure_invariants_hold<MainMarket, BTC>();

    assert!(reserve.cash == 999);
    assert!(reserve.debt == float::one());
    assert!(reserve.cash_reserve.is_zero());

    assert!(reserve.exchange_rate() == math::float::from_quotient(1, 1));
    assert!(reserve.util_rate() == float::from_quotient(1, 1000));

    let remaining = ctokens.split(10, ctx);
    // this is because there isn't as many cash in the pool as part of the cash goes to cash reserve
    std::unit_test::destroy(remaining);

    let btc = reserve.burn_ctokens<MainMarket, BTC>(ctokens);
    reserve.ensure_invariants_hold<MainMarket, BTC>();

    assert!(reserve.cash == 9);
    assert!(reserve.debt.eq(float::from(1)));
    assert!(reserve.cash_reserve.is_zero());

    assert!(btc.value() == 990);

    sui::balance::destroy_for_testing(btc);
    std::unit_test::destroy(reserve);
    scenario_value.end();
}

#[test]
fun test_reserve_repay_more_than_debt() {
    let admin = @0xAD;
    let mut scenario_value = sui::test_scenario::begin(admin);

    let ctx = scenario_value.ctx();
    let mut now = 0;
    let mut reserve = new<MainMarket, BTC>(ctx, now);

    let base = 1000000000;
    let btc = sui::balance::create_for_testing<BTC>(base).into_coin(ctx);
    let ctokens1 = reserve.mint_ctokens<MainMarket, BTC>(btc).into_coin(ctx);

    let amount = 10000;
    let borrowed_balance = reserve.borrow_amount<MainMarket, BTC>(amount);

    now = 11;
    let interest_rate = math::float::from_raw(1);
    let reserve_factor = math::float::from_quotient(1, 100);
    reserve.accrue_interest(reserve_factor, interest_rate, now);

    assert!(reserve.debt == math::float::from_raw(10000000000000000110000));

    let repay_extra = 2;
    let repay_amount = amount + repay_extra;
    let repay_btc = sui::balance::create_for_testing<BTC>(repay_amount).into_coin(ctx);
    reserve.repay_amount<MainMarket, BTC>(repay_btc);
    assert!(reserve.debt.is_zero());
    assert!(reserve.cash == base + repay_extra);
    assert!(reserve.cash_reserve.eq(float::from_raw(1100).add_u64(1)));
    reserve.ensure_invariants_hold<MainMarket, BTC>();

    sui::balance::destroy_for_testing(borrowed_balance);
    std::unit_test::destroy(ctokens1);
    std::unit_test::destroy(reserve);
    scenario_value.end();
}

