#[test]
fun test_reserve_exchange_rate_significant_repay() {
    let admin = @0xAD;
    let mut scenario_value = sui::test_scenario::begin(admin);

    let ctx = scenario_value.ctx();
    let mut now = 0;
    let mut reserve = new<MainMarket, BTC>(ctx, now);

    let amount1 = 1000000000000;
    let amount2 = 100000000000;
    let amount3 = 30000000000000;

    let btc1 = sui::balance::create_for_testing<BTC>(amount1).into_coin(ctx);
    let btc2 = sui::balance::create_for_testing<BTC>(amount2).into_coin(ctx);
    let btc3 = sui::balance::create_for_testing<BTC>(amount3).into_coin(ctx);

    let ctokens1 = reserve.mint_ctokens<MainMarket, BTC>(btc1).into_coin(ctx);
    let ctokens2 = reserve.mint_ctokens<MainMarket, BTC>(btc2).into_coin(ctx);
    let ctokens3 = reserve.mint_ctokens<MainMarket, BTC>(btc3).into_coin(ctx);

    let borrowed_balance = reserve.borrow_amount<MainMarket, BTC>(100000000000);
    assert!(reserve.exchange_rate() == math::float::from_percent(100));
    assert!(reserve.debt.eq(float::from(100000000000)));

    // just a santity check for fun
    reserve.ensure_invariants_hold<MainMarket, BTC>();

    let reserve_factor = float::from_percent(1);
    now = 200; // 200 seconds passed
    // 5% per year
    let interest_rate = math::float::from_quotient(158548959918, 1000000000000000000);
    reserve.accrue_interest(reserve_factor, interest_rate, now);

    assert!(reserve.borrow_index().value().eq(float::from_quotient(1000031709791983600, 1000000000000000000)));
    assert!(reserve.debt.eq(float::from_quotient(10000317097919836, 100000)));

    let repay_btc = sui::balance::create_for_testing<BTC>(reserve.debt.floor()).into_coin(ctx);
    reserve.repay_amount<MainMarket, BTC>(repay_btc);
    assert!(reserve.debt.eq(float::from_quotient(19836, 100000)));
    assert!(reserve.cash == 31100003170979);
    assert!(reserve.cash_reserve.eq(float::from_raw(31709791983600000000000)));
    // python gives: 1.0000001009411386, the difference is very small
    assert!(reserve.exchange_rate() == math::float::from_raw(1000000100941138468));

    let btc1 = reserve.burn_ctokens<MainMarket, BTC>(ctokens1);
    assert!(btc1.value() == 1000000100941);
    // python gives: 1.000000100941143, the difference is very small
    assert!(reserve.exchange_rate() == math::float::from_raw(1000000100941143068));

    let btc2 = reserve.burn_ctokens<MainMarket, BTC>(ctokens2);
    assert!(btc2.value() == 100000010094);

    let btc3 = reserve.burn_ctokens<MainMarket, BTC>(ctokens3);
    assert!(btc3.value() == 30000003028234);

    reserve.ensure_invariants_hold<MainMarket, BTC>();
    // the cash reserve is about 31709 while debt is about 0.19836, the cash available is 31710, as long as cash > reserve + debt, it should be fine
    assert!(reserve.cash_reserve.eq(float::from_raw(31709791983600000000000)));
    assert!(reserve.cash == 31710);
    assert!(reserve.debt.eq(float::from_quotient(19836, 100000)));

    sui::balance::destroy_for_testing(borrowed_balance);
    std::unit_test::destroy(btc1);
    std::unit_test::destroy(btc2);
    std::unit_test::destroy(btc3);
    std::unit_test::destroy(reserve);
    scenario_value.end();
}

